added = 0
for slug in sorted(missing):
    filepath = slug + '/index.html'
    try:
        c = open(filepath, 'r', encoding='utf-8', errors='ignore').read()
    except:
        continue
    
    m = re.search(r'<title>([^<]+)</title>', c)
    title = m.group(1).strip() if m else slug.replace('-',' ').title()
    title = re.sub(r'\s*[-|–]\s*(Free ToolBase|在线小工具|免费在线工具).*$', '', title)
    
    m = re.search(r'<meta\s+name="description"\s+content="([^"]+)"', c)
    desc = m.group(1).strip() if m else title
    if len(desc) > 40: desc = desc[:37] + '...'
    
    cat = get_cat(slug)
    icon = CAT_ICONS.get(cat, '📁')
    href = slug + '/'
    
    if cat not in cn_json:
        cn_json[cat] = []
    cn_json[cat].append([icon, title, desc, href])
    added += 1

with open('tools-data-cn.json', 'w', encoding='utf-8') as f:
    json.dump(cn_json, f, ensure_ascii=False, indent=2)

total = sum(len(v) for v in cn_json.values())
print(f'新增: {added} 工具')
print(f'CN JSON总计: {total} 工具, {len(cn_json)} 分类')
